custom_css:
/* ============================================================
 * Nord-Dark — SillyTavern 主题 v3
 * 设计语言按官方文档（nordtheme.com/docs/colors-and-palettes）+ 官网设计系统：
 * - Polar Night 明度分层：nord0 画布 / nord1 浮起（面板）/ nord2 亮阶·组件底·选中 / nord3 导向标记·发丝线
 * - Snow Storm 文字阶：nord4 正文 / nord5 hover 增亮 / nord6 需更多注意的文字
 * - Frost 强调级：nord8 主强调（primary action/focus） / nord9 次级 / nord10 三级
 * - Aurora 语义态：nord11 错误 / nord13 警告 / nord14 成功（nord15 仅数字字面量）
 * - 官方 passive border = nord1/nord2 发丝线（本主题加回，给结构与设计感）
 * - 官方选区/高亮 = nord2 底 + nord6 字
 * 字体：Rubik（UI）+ HarmonyOS Sans SC（中文回落，可读性）+ Source Code Pro（等宽）
 * 动效：easeOutCubic；圆角 3px（冰/棱角气质）
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/500.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/600.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/source-code-pro@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');

/* ---Nord 原子色（固定，变体不动这层）--- */
:root {
  --nord0:  #2e3440; --nord1:  #3b4252; --nord2:  #434c5e; --nord3:  #4c566a;
  --nord4:  #d8dee9; --nord5:  #e5e9f0; --nord6:  #eceff4;
  --nord7:  #8fbcbb; --nord8:  #88c0d0; --nord9:  #81a1c1; --nord10: #5e81ac;
  --nord11: #bf616a; --nord12: #d08770; --nord13: #ebcb8b; --nord14: #a3be8c; --nord15: #b48ead;

  /* ---语义令牌（变体只改这层）--- */
  --bg-0:        var(--nord0);   /* 画布 */
  --bg-1:        var(--nord1);   /* 面板/抽屉（浮起） */
  --bg-2:        var(--nord2);   /* 组件底/亮阶/选中条 */
  --bg-3:        var(--nord3);   /* 导向标记/滚动条/强发丝线 */
  --bg-sunken:   #282e39;       /* 下沉层 darken(nord0) */
  --line-0:      var(--nord1);  /* 画布级发丝线 */
  --line-1:      var(--nord2);  /* 面板内发丝线 */
  --line-2:      var(--nord3);  /* 组件边/强发丝线 */
  --selection-bg: var(--nord2);
  --selection-fg: var(--nord6);
  --text:        var(--nord4);
  --text-hi:     var(--nord6);
  --text-hover:  var(--nord5);
  --text-dim:    rgba(216, 222, 233, 0.65);
  --text-faint:  var(--nord3);
  --accent:      var(--nord8);   /* ★ 主强调，变体唯一替换点 */
  --accent-2:    var(--nord9);
  --accent-3:    var(--nord10);
  --on-accent:   var(--nord0);
  --danger:      var(--nord11);
  --warn:        var(--nord13);
  --success:     var(--nord14);
  --info:        var(--nord9);
  --frost-ring: 0 0 0 1px var(--accent), 0 0 0 4px rgba(136, 192, 208, 0.18); /* frost 焦点环 */
  --shadow-float: 0 4px 14px rgba(24, 27, 35, 0.4);
  --shadow-raised: 0 1px 3px rgba(24, 27, 35, 0.3);
  --ease-out:    cubic-bezier(0.215, 0.61, 0.355, 1);
  --font-sans: 'Rubik', 'HarmonyOS Sans SC', 'HarmonyOS_Sans_SC', system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  --font-mono: 'Source Code Pro', 'Cascadia Code', ui-monospace, Menlo, Consolas, monospace;
  --radius: 3px;
}

/* ---全局字体（排除图标，避免盖 FA 字形）--- */
body {
  background-color: var(--bg-0) !important;
  color: var(--text) !important;
  font-family: var(--font-sans) !important;
}
input, textarea, select, option,
button:not(.fa-solid):not(.fa-regular):not([class*="fa-"]),
.select2-container, .select2-container .select2-selection,
.text_pole, .widthNatural, #send_textarea, #dialogue_del_mes {
  font-family: var(--font-sans) !important;
}
.mes_text, .mes_text p, .mes_text span,
.ch_name, .mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  font-family: var(--font-sans) !important;
  color: var(--text) !important;
}
.ch_name { color: var(--text-hi) !important; font-weight: 600 !important; letter-spacing: 0.01em !important; }
code, pre, .hljs, .katex { font-family: var(--font-mono) !important; }

/* ---面板/抽屉：nord1 浮起 + nord2 发丝线 + 微浮影（给结构与层次）--- */
.drawer-content,
#left-nav-panel, #right-nav-panel,
#character_popup, #dialogue_popup, .popup,
#top-settings-holder, #send_form,
#WorldInfo, #floatingPrompt, .draggable {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: var(--shadow-raised) !important;
  backdrop-filter: none !important;
  color: var(--text) !important;
}

/* ---标题：nord2 亮条 + 底部 frost 发丝线（层级与 Nord 签名冰线，非 Gruvbox 左边框）--- */
.inline-drawer-header,
.standoutHeader,
.drawer-content h3, .drawer-content h4:not(.margin0),
#character_popup h3, .popup h3 {
  background: var(--bg-2) !important;
  color: var(--text-hi) !important;
  border: none !important;
  border-bottom: 1px solid var(--accent) !important;
  text-shadow: none !important;
  font-weight: 600 !important;
  letter-spacing: 0.02em !important;
  padding: 8px 12px !important;
  border-radius: var(--radius) var(--radius) 0 0 !important;
}
.inline-drawer-header .inline-drawer-icon { color: var(--text-dim) !important; transition: color .12s var(--ease-out) !important; }
.inline-drawer-header:hover .inline-drawer-icon { color: var(--text-hi) !important; }

/* ---按钮：nord2 底 + nord3 细边（可点击感）；hover 升一阶底色；active 转 frost；选中=主强调实底--- */
.menu_button, .right_menu_button,
input[type="button"], input[type="submit"] {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  filter: none !important;
  box-shadow: none !important;
  transition: background-color .14s var(--ease-out), color .14s var(--ease-out), border-color .14s var(--ease-out) !important;
}
.menu_button:hover, .right_menu_button:hover,
input[type="button"]:hover, input[type="submit"]:hover {
  background-color: var(--bg-3) !important;
  color: var(--text-hi) !important;
  border-color: var(--accent) !important;
}
.menu_button:active, .right_menu_button:active,
input[type="button"]:active, input[type="submit"]:active {
  background-color: var(--accent-3) !important;
  color: var(--nord6) !important;
  border-color: var(--accent-3) !important;
}
.menu_button.active, .menu_button.selected {
  background-color: var(--accent) !important;
  color: var(--on-accent) !important;
  border-color: var(--accent) !important;
}

/* ---主操作（发送/继续）：唯一实底冰青；hover 转 nord7（frost 双色阶呼应）--- */
#send_but, #mes_continue {
  background-color: var(--accent) !important;
  color: var(--on-accent) !important;
  border: 1px solid var(--accent) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  filter: none !important;
  box-shadow: none !important;
  transition: background-color .14s var(--ease-out), border-color .14s var(--ease-out) !important;
}
#send_but:hover, #mes_continue:hover {
  background-color: var(--nord7) !important;
  border-color: var(--nord7) !important;
  color: var(--on-accent) !important;
}
#send_but:active, #mes_continue:active {
  background-color: var(--nord9) !important;
  border-color: var(--nord9) !important;
  color: var(--on-accent) !important;
}

/* ---输入区：nord2 底 + nord3 细边；focus frost 焦点环--- */
.text_pole, textarea,
input[type="text"], input[type="password"], input[type="number"],
#send_textarea, select {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  transition: border-color .14s var(--ease-out), box-shadow .14s var(--ease-out) !important;
}
.text_pole:focus, textarea:focus,
input[type="text"]:focus, input[type="password"]:focus,
input[type="number"]:focus, #send_textarea:focus, select:focus {
  border-color: var(--accent) !important;
  box-shadow: var(--frost-ring) !important;
  outline: none !important;
}
.text_pole::placeholder, textarea::placeholder, #send_textarea::placeholder {
  color: var(--text-faint) !important;
  opacity: 1 !important;
}
select option { background-color: var(--bg-1) !important; color: var(--text) !important; }
select option:checked { background-color: var(--selection-bg) !important; color: var(--selection-fg) !important; }

/* ---聊天区：下沉一阶；消息间发丝线分隔；当前消息 nord2 提亮--- */
#chat {
  background-color: var(--bg-sunken) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.mes { border-bottom: 1px solid var(--line-0) !important; }
.last_mes {
  background-color: var(--bg-2) !important;
  border-radius: var(--radius) !important;
}
.mes_text { color: var(--text) !important; }
.mes_block, .mes_text p, .mes_text li { color: var(--text) !important; }
.last_mes .mes_text { color: var(--text) !important; }

/* ---代码块：nord1 浮起 + 发丝线；hljs 严格官方语法色--- */
code, pre {
  background-color: var(--bg-1) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.mes_text code, .mes_text pre { background-color: var(--bg-1) !important; }
.hljs { color: var(--text) !important; background: var(--bg-1) !important; }
.hljs-keyword, .hljs-selector-tag, .hljs-operator, .hljs-punctuation,
.hljs-tag, .hljs-name, .hljs-built_in { color: var(--nord9) !important; }
.hljs-function .hljs-title, .hljs-title.function_, .hljs-section { color: var(--nord8) !important; }
.hljs-title.class_, .hljs-type { color: var(--nord7) !important; }
.hljs-string, .hljs-template-string, .hljs-addition { color: var(--nord14) !important; }
.hljs-number, .hljs-literal { color: var(--nord15) !important; }
.hljs-attr, .hljs-attribute, .hljs-variable, .hljs-constant, .hljs-params { color: var(--nord4) !important; }
.hljs-comment, .hljs-quote { color: var(--nord3) !important; font-style: italic !important; }
.hljs-regexp { color: var(--nord13) !important; }
.hljs-meta { color: var(--nord10) !important; }
.hljs-symbol, .hljs-bullet { color: var(--nord12) !important; }
.hljs-deletion { color: var(--nord11) !important; }
.hljs-emphasis { font-style: italic !important; }
.hljs-strong { font-weight: 700 !important; }

/* ---滚动条：nord3 导向标记色，hover 三级强调--- */
::-webkit-scrollbar { width: 8px !important; height: 8px !important; }
::-webkit-scrollbar-track { background: transparent !important; }
::-webkit-scrollbar-thumb { background: var(--bg-3) !important; border-radius: 2px !important; }
::-webkit-scrollbar-thumb:hover { background: var(--accent-3) !important; }
::-webkit-scrollbar-corner { background: transparent !important; }
* { scrollbar-color: var(--bg-3) transparent !important; scrollbar-width: thin !important; }

/* ---选区：官方 = nord2 底 + nord6 字--- */
::selection { background: var(--selection-bg) !important; color: var(--selection-fg) !important; }

/* ---标签 tag：次级强调 nord9 淡底 + nord9 细边--- */
.tag {
  background-color: rgba(129, 161, 193, 0.14) !important;
  color: var(--accent-2) !important;
  border: 1px solid rgba(129, 161, 193, 0.4) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.tag::before { color: var(--accent-2) !important; }

/* ---滑条/勾选/单选--- */
input[type="range"] {
  background: var(--bg-2) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  filter: none !important;
  box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-3) !important;
  border-radius: 50% !important;
  box-shadow: none !important;
}
input[type="range"]::-moz-range-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-3) !important;
  border-radius: 50% !important;
}
input[type="checkbox"], input[type="radio"] { accent-color: var(--accent) !important; }

/* ---浮层微阴影--- */
#character_popup, #dialogue_popup, .popup, .draggable,
.toast, .toast-container .toast,
.tooltip, .tooltip-inner {
  box-shadow: var(--shadow-float) !important;
}

/* ---弹窗/toastr：nord2 浮层 + 发丝线，语义色染标题--- */
.toast, .toast-container .toast {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
}
.toast-success .toast-title { color: var(--success) !important; }
.toast-error .toast-title { color: var(--danger) !important; }
.toast-warning .toast-title { color: var(--warn) !important; }
.toast-info .toast-title { color: var(--info) !important; }

/* ---头像：纯圆角，不描边--- */
.avatar, .avatar img { border: none !important; border-radius: var(--radius) !important; }

/* ---顶栏图标：只改颜色与 hover（不沿用 Gruvbox 的 openIcon 满高/topBarIconSize 配方）--- */
#top-settings-holder .drawer-icon {
  color: var(--text-dim) !important;
  text-shadow: none !important;
  filter: none !important;
  transition: color .14s var(--ease-out) !important;
}
#top-settings-holder .drawer-icon:hover { color: var(--accent) !important; }
#top-settings-holder .drawer-icon.openIcon { color: var(--text-hi) !important; }

/* ---链接：主强调，hover 加下划线--- */
a, a:visited { color: var(--accent) !important; text-decoration: none !important; }
a:hover { text-decoration: underline !important; }

/* ---工具提示 tooltip--- */
.tooltip, [data-toggle="tooltip"] + .tooltip, .tooltip-inner, .tooltip-arrow {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

/* ---列表条目：面板内发丝线分隔，hover 升一阶--- */
.character_div, .character_select,
#WorldInfo .world_entry,
.prompt_manager_prompt_entry,
.world_info_entry {
  border-bottom: 1px solid var(--line-1) !important;
  background-color: transparent !important;
}
.character_div:hover, .character_select:hover,
#WorldInfo .world_entry:hover, .world_info_entry:hover {
  background-color: var(--bg-2) !important;
}

/* ---分割线--- */
hr, .drawer-content hr { border: none !important; border-top: 1px solid var(--line-1) !important; }
.mes hr, .mes_text hr { border: none !important; border-top: 1px solid var(--line-0) !important; }

/* ---全局克制：去文字阴影/入场动画--- */
* { text-shadow: none !important; }
.mes, .drawer-content { animation: none !important; }

/* ============================================================
 * modern-ui 插件适配（body.th-modern-enabled 限定，纯 ST 零命中）
 * ============================================================ */
body.th-modern-enabled .th-modern-wi-entry,
body.th-modern-enabled .th-modern-wi-list,
body.th-modern-enabled [class^="th-modern-wi"] {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  color: var(--text) !important;
}
body.th-modern-enabled .th-modern-panel-header,
body.th-modern-enabled .th-modern-section-title,
body.th-modern-enabled .th-modern-wi-header {
  background: var(--bg-2) !important;
  color: var(--text-hi) !important;
  border: none !important;
  border-bottom: 1px solid var(--accent) !important;
  border-radius: var(--radius) var(--radius) 0 0 !important;
}
body.th-modern-enabled input.th-modern-wi-shortcut-control[type="text"],
body.th-modern-enabled input.th-modern-wi-shortcut-control[type="number"],
body.th-modern-enabled select.th-modern-wi-shortcut-control {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card,
body.th-modern-enabled .th-modern-item {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card:hover,
body.th-modern-enabled .th-modern-item:hover {
  background-color: var(--bg-2) !important;
  border-color: var(--accent) !important;
}

/* ---modern-ui select 弹层主题化（PC 专用，塞桌面媒体）--- */
@media (hover: hover) and (pointer: fine) {
  body.th-modern-enabled .select2-container--default .select2-results__option--highlighted[aria-selected] {
    background-color: var(--selection-bg) !important;
    color: var(--selection-fg) !important;
  }
  body.th-modern-enabled .select2-container--default .select2-selection--single {
    background-color: var(--bg-2) !important;
    color: var(--text) !important;
    border: 1px solid var(--line-2) !important;
    border-radius: var(--radius) !important;
  }
}

/* ============================================================
 * Nord-Contour 纹理 + UI 透明化 + logo
 * 背景：两角 wavy concentric（左下 nord10/nord9、右上 nord8/nord7），
 *       每层同形状放大、Catmull-Rom 平滑，两角同色系(frost)起点；
 *       中心由两层 nord0 构成结构感。
 * aurora 点缀：角色名红 nord11、标签紫 nord15。
 * UI 透明化：消息/聊表半透浮在纹理上，面板半透玻璃，顶栏/输入栏也透。
 * ============================================================ */
